  function equipPendingEssence(){const pending=game.essences.pending;if(pending==='shadow'&&!game.essences.shadow){game.essences.shadow=true;delete game.essences.pending;const slot=$$('[data-slot]').find(el=>!el.dataset.essenceName)||document.querySelector('[data-essence="slot1"]');slot.classList.remove('empty');slot.classList.add('equipped');slot.dataset.essenceName='shadow';const index=Number(slot.dataset.slot);slot.innerHTML='<span class="essence-symbol shadow-symbol">◈</span><span><b>SHADOW</b><small>ASSASSIN • UNCOMMON</small></span><i>'+String(index).padStart(2,'0')+'</i>';const skill=document.querySelector(`[data-skill="${index}"]`)||document.querySelector('[data-skill="1"]');skill.classList.remove('disabled');skill.querySelector('small').textContent='SHADOW STEP';toast('Shadow essence equipped • Shadow Step unlocked');return}if(pending==='blood'&&!game.essences.blood){game.essences.blood=true;delete game.essences.pending;const slot=$$('[data-slot]').find(el=>!el.dataset.essenceName);if(slot){const index=Number(slot.dataset.slot);slot.classList.remove('empty');slot.classList.add('equipped');slot.dataset.essenceName='blood';slot.innerHTML='<span class="essence-symbol blood-symbol">✹</span><span><b>BLOOD</b><small>RIFT ESSENCE • RARE</small></span><i>'+String(index).padStart(2,'0')+'</i>';const skill=document.querySelector(`[data-skill="${index}"]`)||document.querySelector('[data-skill="2"]');skill.classList.remove('disabled');skill.querySelector('small').textContent='BLOOD BOLT'}toast('Blood essence equipped');}}
